#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import prettier from 'prettier';
import { scanApiMessageSources } from './api-message-source-lib.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const manifest = scanApiMessageSources(root);
const definitions = [
  '// Generated by bin/update-api-message-catalog.mjs; source callsites are recorded in config/i18n/api-message-sources.json.',
  "import defineMessages from '@app/utils/defineMessages';",
  '',
  "export const apiMessages: Record<string, { id: string; defaultMessage: string }> = defineMessages('utils.ApiMessage', {",
  ...manifest.entries.map(
    (entry) => `  ${entry.key}: ${JSON.stringify(entry.defaultMessage)},`
  ),
  '});',
  '',
  'export const apiMessagePatterns: readonly (readonly [string, readonly string[]])[] = [',
  ...manifest.entries.map(
    (entry) =>
      `  [${JSON.stringify(entry.key)}, ${JSON.stringify(entry.parts)}],`
  ),
  '];',
  '',
].join('\n');
const authoredOutputs = [
  [
    'config/i18n/api-message-sources.json',
    JSON.stringify(manifest, null, 2) + '\n',
  ],
  ['src/i18n/apiMessages.ts', definitions],
];
const outputs = new Map(
  await Promise.all(
    authoredOutputs.map(async ([file, value]) => [
      file,
      await prettier.format(value, {
        ...(await prettier.resolveConfig(path.join(root, file))),
        filepath: path.join(root, file),
      }),
    ])
  )
);
if (process.argv.includes('--check')) {
  const stale = [...outputs].filter(
    ([file, value]) =>
      !fs.existsSync(path.join(root, file)) ||
      fs.readFileSync(path.join(root, file), 'utf8') !== value
  );
  if (stale.length) {
    console.error(
      'API message source coverage changed. Run node bin/update-api-message-catalog.mjs and synchronize locale catalogs.'
    );
    for (const [file] of stale) console.error(file);
    process.exitCode = 1;
  } else
    console.log(
      `API message source coverage matches ${manifest.entries.length} messages.`
    );
} else {
  for (const [file, value] of outputs)
    fs.writeFileSync(path.join(root, file), value);
  console.log(
    `Generated ${manifest.entries.length} source-bound API messages and ${manifest.opaque.length} opaque/code records.`
  );
}
